def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def best_by(items, score_fn):
        best_item = None
        best_score = None
        for item in items:
            try:
                sc = score_fn(item)
            except Exception:
                continue
            if best_item is None or sc < best_score:
                best_item = item
                best_score = sc
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    def step_toward(tx, ty):
        return [sgn(tx - sx), sgn(ty - sy)]

    def step_away(tx, ty):
        return [sgn(sx - tx), sgn(sy - ty)]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(ox, oy)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = best_by(corners, lambda c: -(abs(c[0] - ox) + abs(c[1] - oy)))
        if target is None:
            return step_away(ox, oy)
        return step_toward(target[0], target[1])

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        if targets:
            target = best_by(targets, lambda c: abs(c[0] - sx) + abs(c[1] - sy))
            if target is not None:
                return step_toward(target[0], target[1])
        return step_toward(ox, oy)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        def resource_score(r):
            rx, ry = pos(r, (sx, sy))
            val = 1
            if isinstance(r, dict):
                val = r.get("value", r.get("amount", 1))
            d = abs(rx - sx) + abs(ry - sy)
            return (d - val * 0.25, d)
        target = best_by(resources, resource_score)
        if target is not None:
            tx, ty = pos(target, (sx, sy))
            return step_toward(tx, ty)

    return step_away(ox, oy)

